mapper.select:
SELECT 'PUR_REQUEST' AS kind, '구매요청' AS kind_label, r.request_no AS no, r.request_seq AS seq, r.request_status AS status, 'REQUEST_STATUS' AS status_group, COALESCE(pl.plant_name, '') AS label, (SELECT SUM(l.request_qty)::int FROM tb_purchase_request_line l WHERE l.request_seq = r.request_seq) AS qty, r.requested_at AS when, 'purchase-requests' AS route, TRUE AS reached FROM tb_purchase_request r LEFT JOIN tb_plant pl ON pl.plant_seq = r.plant_seq WHERE r.request_seq = #{requestSeq}
UNION ALL
SELECT 'PUR_ORDER', '발주', o.order_no, o.order_seq, o.order_status, 'PO_STATUS', COALESCE(pt.partner_name, ''), (SELECT SUM(l.order_qty)::int FROM tb_purchase_order_line l WHERE l.order_seq = o.order_seq), o.created_at, 'purchase-orders', TRUE FROM tb_purchase_order o LEFT JOIN tb_partner pt ON pt.partner_seq = o.supplier_seq WHERE o.request_seq = #{requestSeq}
UNION ALL
SELECT 'INBOUND', '입고', i.inbound_no, i.inbound_seq, i.inbound_status, 'INBOUND_STATUS', COALESCE(pl2.plant_name, ''), (SELECT SUM(l.planned_qty)::int FROM tb_inbound_line l WHERE l.inbound_seq = i.inbound_seq), i.created_at, 'inbound-plans', TRUE FROM tb_inbound i JOIN tb_purchase_order o2 ON o2.order_seq = i.order_seq LEFT JOIN tb_plant pl2 ON pl2.plant_seq = i.plant_seq WHERE o2.request_seq = #{requestSeq}
ORDER BY 9, 4
